-- MARKET POS V2: SALES, PAYMENTS, MINIMAL SHIFTS AND FISCAL INTENTS
-- Additive coexistence: legacy sales, sale_items, payments and shifts remain untouched.

-- Permission registry and discount templates ---------------------------------
alter table public.permissions disable trigger v2_permissions_prevent_insert;
insert into public.permissions(code,module,description,critical)values
('sales.cost.view','sales','View sale cost snapshots, batch allocations and gross margin.',false)
on conflict(code)do update set module=excluded.module,description=excluded.description,critical=excluded.critical;
alter table public.permissions enable trigger v2_permissions_prevent_insert;

insert into public.permission_profile_permissions(permission_profile_id,permission_id)
select '00000000-0000-0000-0000-000000000101'::uuid,id from public.permissions where code='sales.cost.view'
on conflict do nothing;

update public.permission_profile_permissions ppp set constraints='{"max_discount_percent":100}'::jsonb
from public.permissions p where p.id=ppp.permission_id and p.code='sales.discount'
and ppp.permission_profile_id='00000000-0000-0000-0000-000000000101';
update public.permission_profile_permissions ppp set constraints='{"max_discount_percent":0}'::jsonb
from public.permissions p where p.id=ppp.permission_id and p.code='sales.discount'
and ppp.permission_profile_id='00000000-0000-0000-0000-000000000102';
update public.organization_memberships om set permission_version=permission_version+1
where om.status='active'and exists(select 1 from public.membership_permission_profiles mpp where mpp.membership_id=om.id and mpp.permission_profile_id in('00000000-0000-0000-0000-000000000101','00000000-0000-0000-0000-000000000102'));

-- Inventory source identity now supports sale allocations and multi-batch returns.
alter table public.inventory_movements drop constraint inventory_movements_source_check;
do $$declare n text;begin select conname into n from pg_constraint where conrelid='public.inventory_movements'::regclass and contype='u'and pg_get_constraintdef(oid)like 'UNIQUE (source_document_type, source_line_id, movement_role)%';if n is not null then execute format('alter table public.inventory_movements drop constraint %I',n);end if;end$$;
alter table public.inventory_movements add constraint inventory_movements_source_check check(source_document_type in('purchase','inventory_document','warehouse_transfer','sale','sale_return'));
create unique index inventory_movements_source_batch_key on public.inventory_movements(source_document_type,source_line_id,movement_role,batch_id) nulls not distinct;

-- Minimal V2 shifts -----------------------------------------------------------
create table public.shifts_v2(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 branch_id uuid not null references public.branches(id)on delete restrict,register_id uuid not null references public.registers(id)on delete restrict,
 opened_by uuid not null references public.organization_memberships(id)on delete restrict,opening_cash_amount numeric(18,4)not null default 0,
 status text not null default'open',opened_at timestamptz not null default now(),closed_by uuid references public.organization_memberships(id)on delete restrict,
 closed_at timestamptz,actual_cash_amount numeric(18,4),difference_amount numeric(18,4),version bigint not null default 1,created_at timestamptz not null default now(),
 constraint shifts_v2_opening_check check(opening_cash_amount>=0),constraint shifts_v2_status_check check(status in('open','closing','closed')),
 constraint shifts_v2_close_shape_check check((status='closed'and closed_by is not null and closed_at is not null and actual_cash_amount is not null and difference_amount is not null)or(status in('open','closing')and closed_by is null and closed_at is null))
);
create unique index shifts_v2_one_open_register on public.shifts_v2(register_id)where status in('open','closing');
create index shifts_v2_branch_opened_idx on public.shifts_v2(branch_id,opened_at desc);

create table public.shift_totals(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 shift_id uuid not null references public.shifts_v2(id)on delete restrict,payment_method text not null,expected_amount numeric(18,4)not null default 0,
 actual_amount numeric(18,4),version bigint not null default 0,updated_at timestamptz not null default now(),
 constraint shift_totals_method_check check(payment_method in('cash','card','transfer')),unique(shift_id,payment_method)
);

-- Posted sale graph -----------------------------------------------------------
create table public.sales_v2(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 branch_id uuid not null references public.branches(id)on delete restrict,register_id uuid not null references public.registers(id)on delete restrict,
 warehouse_id uuid not null references public.warehouses(id)on delete restrict,shift_id uuid not null references public.shifts_v2(id)on delete restrict,
 customer_counterparty_id uuid references public.counterparties(id)on delete restrict,document_number text not null,business_date date not null,
 status text not null default'posted',currency_code char(3)not null,subtotal_amount numeric(18,4)not null,discount_amount numeric(18,4)not null default 0,
 tax_amount numeric(18,4)not null default 0,total_amount numeric(18,4)not null,paid_amount numeric(18,4)not null,debt_amount numeric(18,4)not null default 0,
 device_id uuid not null references public.devices_v2(id)on delete restrict,local_operation_id uuid not null,client_created_at timestamptz not null,
 posted_by uuid not null references public.organization_memberships(id)on delete restrict,posted_at timestamptz not null default now(),
 reversal_of_id uuid references public.sales_v2(id)on delete restrict,created_at timestamptz not null default now(),
 constraint sales_v2_number_check check(btrim(document_number)<>''),constraint sales_v2_status_check check(status in('posted','partially_returned','returned','reversed')),
 constraint sales_v2_currency_check check(currency_code~'^[A-Z]{3}$'),constraint sales_v2_amounts_check check(subtotal_amount>=0 and discount_amount>=0 and tax_amount=0 and total_amount>=0 and paid_amount>=0 and debt_amount=0 and total_amount=subtotal_amount-discount_amount and paid_amount=total_amount),
 unique(organization_id,document_number),unique(organization_id,device_id,local_operation_id)
);
create unique index sales_v2_one_reversal on public.sales_v2(reversal_of_id)where reversal_of_id is not null;
create index sales_v2_journal_idx on public.sales_v2(branch_id,business_date desc,status);
create index sales_v2_shift_idx on public.sales_v2(shift_id,posted_at);

create table public.sale_lines_v2(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 sale_id uuid not null references public.sales_v2(id)on delete restrict,line_number integer not null,product_id uuid not null references public.products_v2(id)on delete restrict,
 product_name_snapshot text not null,unit_id uuid not null references public.units_v2(id)on delete restrict,unit_name_snapshot text not null,
 product_price_id uuid not null references public.product_prices(id)on delete restrict,quantity numeric(18,6)not null,unit_factor numeric(20,10)not null,
 base_quantity numeric(18,6)not null,unit_sale_price numeric(18,4)not null,unit_cost numeric(18,4)not null,discount_amount numeric(18,4)not null default 0,
 tax_amount numeric(18,4)not null default 0,line_total_amount numeric(18,4)not null,created_at timestamptz not null default now(),
 constraint sale_lines_v2_number_check check(line_number>0),constraint sale_lines_v2_quantity_check check(quantity>0 and unit_factor>0 and base_quantity>0),
 constraint sale_lines_v2_amount_check check(unit_sale_price>=0 and unit_cost>=0 and discount_amount>=0 and tax_amount=0 and line_total_amount>=0),unique(sale_id,line_number)
);

create table public.sale_line_batch_allocations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 sale_line_id uuid not null references public.sale_lines_v2(id)on delete restrict,product_batch_id uuid not null references public.product_batches_v2(id)on delete restrict,
 quantity numeric(18,6)not null,unit_cost numeric(18,4)not null,inventory_movement_id uuid not null references public.inventory_movements(id)on delete restrict deferrable initially deferred,
 created_at timestamptz not null default now(),constraint sale_allocations_quantity_check check(quantity>0),constraint sale_allocations_cost_check check(unit_cost>=0),unique(sale_line_id,product_batch_id),unique(inventory_movement_id)
);

create table public.held_sales(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 branch_id uuid not null references public.branches(id)on delete restrict,register_id uuid not null references public.registers(id)on delete restrict,
 created_by uuid not null references public.organization_memberships(id)on delete restrict,cart_payload jsonb not null,expires_at timestamptz not null,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint held_sales_payload_object_check check(jsonb_typeof(cart_payload)='object')
);
create index held_sales_scope_idx on public.held_sales(register_id,created_by,updated_at desc);
create index held_sales_expiry_idx on public.held_sales(expires_at);

create table public.sale_returns(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 original_sale_id uuid not null references public.sales_v2(id)on delete restrict,register_id uuid not null references public.registers(id)on delete restrict,
 shift_id uuid not null references public.shifts_v2(id)on delete restrict,document_number text not null,status text not null default'posted',
 total_amount numeric(18,4)not null,debt_reduction_amount numeric(18,4)not null default 0,device_id uuid not null references public.devices_v2(id)on delete restrict,
 local_operation_id uuid not null,posted_by uuid not null references public.organization_memberships(id)on delete restrict,posted_at timestamptz not null default now(),
 reversal_of_id uuid references public.sale_returns(id)on delete restrict,created_at timestamptz not null default now(),
 constraint sale_returns_number_check check(btrim(document_number)<>''),constraint sale_returns_status_check check(status in('posted','reversed')),
 constraint sale_returns_amount_check check(total_amount>=0 and debt_reduction_amount=0),unique(organization_id,document_number),unique(organization_id,device_id,local_operation_id)
);
create unique index sale_returns_one_reversal on public.sale_returns(reversal_of_id)where reversal_of_id is not null;

create table public.sale_return_lines(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 sale_return_id uuid not null references public.sale_returns(id)on delete restrict,original_sale_line_id uuid not null references public.sale_lines_v2(id)on delete restrict,
 quantity numeric(18,6)not null,refund_amount numeric(18,4)not null,debt_reduction_amount numeric(18,4)not null default 0,created_at timestamptz not null default now(),
 constraint sale_return_lines_quantity_check check(quantity>0),constraint sale_return_lines_amount_check check(refund_amount>=0 and debt_reduction_amount=0),unique(sale_return_id,original_sale_line_id)
);

create table public.payments_v2(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 branch_id uuid not null references public.branches(id)on delete restrict,register_id uuid not null references public.registers(id)on delete restrict,
 shift_id uuid not null references public.shifts_v2(id)on delete restrict,sale_id uuid references public.sales_v2(id)on delete restrict,
 sale_return_id uuid references public.sale_returns(id)on delete restrict,method text not null,amount numeric(18,4)not null,currency_code char(3)not null,
 status text not null default'confirmed',device_id uuid not null references public.devices_v2(id)on delete restrict,local_operation_id uuid not null,
 reversal_of_id uuid references public.payments_v2(id)on delete restrict,created_by uuid not null references public.organization_memberships(id)on delete restrict,created_at timestamptz not null default now(),
 constraint payments_v2_source_check check((sale_id is not null)::integer+(sale_return_id is not null)::integer=1),constraint payments_v2_method_check check(method in('cash','card','transfer')),
 constraint payments_v2_amount_check check(amount<>0),constraint payments_v2_currency_check check(currency_code~'^[A-Z]{3}$'),constraint payments_v2_status_check check(status='confirmed'),
 unique(organization_id,device_id,local_operation_id)
);
create index payments_v2_shift_method_idx on public.payments_v2(shift_id,method,created_at);
create index payments_v2_sale_idx on public.payments_v2(sale_id)where sale_id is not null;

-- Fiscal settings and intents -------------------------------------------------
create or replace function public.v2_fiscal_settings_valid(s jsonb)returns boolean language sql immutable set search_path=''as $$
 select case when s is null or not(s?'fiscal')then true when jsonb_typeof(s->'fiscal')<>'object'then false when exists(select 1 from jsonb_object_keys(s->'fiscal')k where k not in('mode','provider_code','offline_policy'))then false else
  case coalesce(s#>>'{fiscal,mode}','disabled')when'disabled'then coalesce(jsonb_typeof(s#>'{fiscal,provider_code}'),'null')='null'and coalesce(s#>>'{fiscal,offline_policy}','reject')='reject'
  when'required'then nullif(btrim(s#>>'{fiscal,provider_code}'),'')is not null and coalesce(s#>>'{fiscal,offline_policy}','reject')='reject'
  when'deferred'then nullif(btrim(s#>>'{fiscal,provider_code}'),'')is not null and coalesce(s#>>'{fiscal,offline_policy}','defer')='defer' else false end end
$$;
alter table public.registers add constraint registers_fiscal_settings_check check(public.v2_fiscal_settings_valid(settings))not valid;

create table public.fiscal_documents(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 branch_id uuid not null references public.branches(id)on delete restrict,register_id uuid not null references public.registers(id)on delete restrict,
 shift_id uuid not null references public.shifts_v2(id)on delete restrict,sale_id uuid references public.sales_v2(id)on delete restrict,
 sale_return_id uuid references public.sale_returns(id)on delete restrict,provider_code text not null,status text not null default'pending',idempotency_key text not null,
 external_receipt_id text,fiscal_sign text,processing_token uuid,processing_started_at timestamptz,issued_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint fiscal_documents_source_check check((sale_id is not null)::integer+(sale_return_id is not null)::integer=1),constraint fiscal_documents_provider_check check(btrim(provider_code)<>''),
 constraint fiscal_documents_status_check check(status in('pending','processing','issued','deferred','failed','cancelled')),
 constraint fiscal_documents_processing_check check((status='processing'and processing_token is not null and processing_started_at is not null)or(status<>'processing'and processing_token is null and processing_started_at is null)),
 constraint fiscal_documents_issued_check check(status<>'issued'or(issued_at is not null and external_receipt_id is not null)),unique(sale_id),unique(sale_return_id),unique(organization_id,provider_code,idempotency_key)
);

create table public.fiscal_attempts(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete restrict,
 fiscal_document_id uuid not null references public.fiscal_documents(id)on delete restrict,attempt_number integer not null,request_hash text not null,outcome text not null,
 response_code text,response_payload jsonb,error_code text,created_at timestamptz not null default now(),constraint fiscal_attempt_number_check check(attempt_number>0),
 constraint fiscal_attempt_outcome_check check(outcome in('issued','failed','deferred')),constraint fiscal_attempt_response_object_check check(response_payload is null or jsonb_typeof(response_payload)='object'),unique(fiscal_document_id,attempt_number)
);

-- Authorization and defensive guards ----------------------------------------
create or replace function public.v2_effective_discount_limit(o uuid)returns numeric language sql stable security definer set search_path=''as $$
 select case when exists(select 1 from public.organization_memberships om join public.user_profiles up on up.id=om.user_profile_id where om.organization_id=o and om.status='active'and up.status='active'and up.auth_user_id=auth.uid()and om.system_role='owner')then 100::numeric else coalesce((select max(case when jsonb_typeof(ppp.constraints->'max_discount_percent')='number'and(ppp.constraints->>'max_discount_percent')::numeric between 0 and 100 then(ppp.constraints->>'max_discount_percent')::numeric else 0 end)from public.organization_memberships om join public.user_profiles up on up.id=om.user_profile_id join public.membership_permission_profiles mpp on mpp.membership_id=om.id join public.permission_profiles pp on pp.id=mpp.permission_profile_id and pp.archived_at is null join public.permission_profile_permissions ppp on ppp.permission_profile_id=pp.id join public.permissions p on p.id=ppp.permission_id and p.code='sales.discount'where om.organization_id=o and om.status='active'and up.status='active'and up.auth_user_id=auth.uid()),0)end
$$;
create or replace function public.v2_can_view_sale(o uuid,b uuid,s uuid,cost boolean default false)returns boolean language sql stable security definer set search_path=''as $$
 select (public.v2_has_permission(o,'sales.view',b)and(not cost or public.v2_has_permission(o,'sales.cost.view',b))and exists(select 1 from public.organization_memberships om join public.user_profiles up on up.id=om.user_profile_id where om.organization_id=o and up.auth_user_id=auth.uid()and om.status='active'and up.status='active'and(om.system_role='owner'or exists(select 1 from public.shifts_v2 x where x.id=s and x.opened_by=om.id))))
 or(public.v2_has_support_grant(o,'sales.view')and(not cost or public.v2_has_support_grant(o,'sales.cost.view')))
$$;
create or replace function public.v2_sales_context_required()returns trigger language plpgsql set search_path=''as $$begin if coalesce(current_setting('market_pos.sales_command',true),'')<>'on'then raise exception using errcode='P0001',message='V2_SALES_COMMAND_CONTEXT_REQUIRED';end if;return coalesce(new,old);end$$;
create or replace function public.v2_sales_append_only()returns trigger language plpgsql set search_path=''as $$begin if coalesce(current_setting('market_pos.sales_command',true),'')='on'then return coalesce(new,old);end if;raise exception using errcode='P0001',message='V2_SALES_APPEND_ONLY';end$$;
create or replace function public.v2_shift_guard()returns trigger language plpgsql set search_path=''as $$
begin if not exists(select 1 from public.registers r where r.id=new.register_id and r.organization_id=new.organization_id and r.branch_id=new.branch_id and r.status='active')then raise exception using errcode='P0001',message='V2_SHIFT_REGISTER_SCOPE_MISMATCH';end if;if not exists(select 1 from public.organization_memberships m where m.id=new.opened_by and m.organization_id=new.organization_id)or(new.closed_by is not null and not exists(select 1 from public.organization_memberships m where m.id=new.closed_by and m.organization_id=new.organization_id))then raise exception using errcode='P0001',message='V2_SHIFT_ACTOR_SCOPE_MISMATCH';end if;if tg_op='UPDATE'then if old.status='closed'or new.id<>old.id or new.organization_id<>old.organization_id or new.branch_id<>old.branch_id or new.register_id<>old.register_id or new.opened_by<>old.opened_by or new.opened_at<>old.opened_at or new.opening_cash_amount<>old.opening_cash_amount or new.created_at<>old.created_at then raise exception using errcode='P0001',message='V2_SHIFT_CLOSED_IMMUTABLE';end if;end if;return new;end$$;
create or replace function public.v2_shift_total_guard()returns trigger language plpgsql set search_path=''as $$
declare st text;o uuid;begin select status,organization_id into st,o from public.shifts_v2 where id=new.shift_id;if o is distinct from new.organization_id then raise exception using errcode='P0001',message='V2_SHIFT_TOTAL_SCOPE_MISMATCH';end if;if st<>'open'then raise exception using errcode='P0001',message='V2_SHIFT_TOTAL_FROZEN';end if;return new;end$$;
create or replace function public.v2_sale_graph_guard()returns trigger language plpgsql set search_path=''as $$
declare o uuid;b uuid;r uuid;w uuid;s uuid;begin
 if tg_table_name='sales_v2'then if not exists(select 1 from public.registers x where x.id=new.register_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id)or not exists(select 1 from public.warehouses x where x.id=new.warehouse_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id)or not exists(select 1 from public.devices_v2 x where x.id=new.device_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id and x.register_id=new.register_id and x.status='trusted')or not exists(select 1 from public.shifts_v2 x where x.id=new.shift_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id and x.register_id=new.register_id)then raise exception using errcode='P0001',message='V2_SALE_LOCATION_SCOPE_MISMATCH';end if;if new.customer_counterparty_id is not null and not exists(select 1 from public.counterparty_roles cr where cr.counterparty_id=new.customer_counterparty_id and cr.organization_id=new.organization_id and cr.role_code='customer'and cr.ended_at is null)then raise exception using errcode='P0001',message='V2_SALE_ACTIVE_CUSTOMER_REQUIRED';end if;if new.debt_amount<>0 then raise exception using errcode='P0001',message='V2_SALE_DEBT_NOT_AVAILABLE_BEFORE_0015';end if;if tg_op='UPDATE'and(to_jsonb(new)-'status')<>(to_jsonb(old)-'status')then raise exception using errcode='P0001',message='V2_SALE_POSTED_IMMUTABLE';end if;
 elsif tg_table_name='sale_lines_v2'then select organization_id,branch_id,register_id,warehouse_id,shift_id into o,b,r,w,s from public.sales_v2 where id=new.sale_id;if o is distinct from new.organization_id then raise exception using errcode='P0001',message='V2_SALE_LINE_SCOPE_MISMATCH';end if;
 elsif tg_table_name='sale_line_batch_allocations'then select sl.organization_id,sv.warehouse_id into o,w from public.sale_lines_v2 sl join public.sales_v2 sv on sv.id=sl.sale_id where sl.id=new.sale_line_id;if o is distinct from new.organization_id or not exists(select 1 from public.product_batches_v2 pb join public.sale_lines_v2 sl on sl.id=new.sale_line_id where pb.id=new.product_batch_id and pb.organization_id=new.organization_id and pb.warehouse_id=w and pb.product_id=sl.product_id)then raise exception using errcode='P0001',message='V2_SALE_ALLOCATION_SCOPE_MISMATCH';end if;
 end if;return new;end$$;
create or replace function public.v2_payment_guard()returns trigger language plpgsql set search_path=''as $$declare o uuid;b uuid;r uuid;s uuid;c char(3);original public.payments_v2%rowtype;refunded numeric;begin
 if new.sale_id is not null then select organization_id,branch_id,register_id,shift_id,currency_code into o,b,r,s,c from public.sales_v2 where id=new.sale_id;else select sr.organization_id,sv.branch_id,sr.register_id,sr.shift_id,sv.currency_code into o,b,r,s,c from public.sale_returns sr join public.sales_v2 sv on sv.id=sr.original_sale_id where sr.id=new.sale_return_id;end if;
 if new.organization_id is distinct from o or new.branch_id is distinct from b or new.register_id is distinct from r or new.shift_id is distinct from s or new.currency_code<>c then raise exception using errcode='P0001',message='V2_PAYMENT_SOURCE_SCOPE_MISMATCH';end if;
 if new.reversal_of_id is not null then select * into original from public.payments_v2 where id=new.reversal_of_id;if not found or original.organization_id<>new.organization_id or original.method<>new.method or original.currency_code<>new.currency_code then raise exception using errcode='P0001',message='V2_PAYMENT_REVERSAL_MISMATCH';end if;if original.amount>0 and new.sale_return_id is not null then select coalesce(sum(abs(p.amount)),0)into refunded from public.payments_v2 p where p.reversal_of_id=original.id and p.amount<0 and p.status='confirmed'and not exists(select 1 from public.payments_v2 opposite where opposite.reversal_of_id=p.id and opposite.amount>0 and opposite.status='confirmed');if new.amount>=0 or refunded+abs(new.amount)>original.amount then raise exception using errcode='P0001',message='V2_PAYMENT_REFUND_EXCEEDED';end if;elsif new.amount<>-original.amount then raise exception using errcode='P0001',message='V2_PAYMENT_REVERSAL_MISMATCH';end if;
 elsif new.sale_id is not null then if new.amount<=0 then raise exception using errcode='P0001',message='V2_PAYMENT_SIGN_MISMATCH';end if;
 else raise exception using errcode='P0001',message='V2_PAYMENT_REFUND_SOURCE_REQUIRED';
 end if;return new;end$$;
create or replace function public.v2_fiscal_document_guard()returns trigger language plpgsql set search_path=''as $$begin if tg_op='UPDATE'and old.status in('issued','cancelled')then raise exception using errcode='P0001',message='V2_FISCAL_TERMINAL';end if;return new;end$$;

create trigger v2_shifts_context before insert or update or delete on public.shifts_v2 for each row execute function public.v2_sales_context_required();create trigger v2_shifts_guard before insert or update on public.shifts_v2 for each row execute function public.v2_shift_guard();create trigger v2_shifts_delete before delete on public.shifts_v2 for each row execute function public.v2_sales_append_only();
create trigger v2_shift_totals_context before insert or update or delete on public.shift_totals for each row execute function public.v2_sales_context_required();create trigger v2_shift_totals_guard before insert or update on public.shift_totals for each row execute function public.v2_shift_total_guard();
create trigger v2_sales_context before insert or update or delete on public.sales_v2 for each row execute function public.v2_sales_context_required();create trigger v2_sales_guard before insert or update on public.sales_v2 for each row execute function public.v2_sale_graph_guard();create trigger v2_sales_delete before delete on public.sales_v2 for each row execute function public.v2_sales_append_only();
create trigger v2_sale_lines_context before insert or update or delete on public.sale_lines_v2 for each row execute function public.v2_sales_context_required();create trigger v2_sale_lines_guard before insert or update on public.sale_lines_v2 for each row execute function public.v2_sale_graph_guard();create trigger v2_sale_lines_append_only before update or delete on public.sale_lines_v2 for each row execute function public.v2_sales_append_only();
