-- RLS and safe reads ----------------------------------------------------------
alter table public.shifts_v2 enable row level security;alter table public.shift_totals enable row level security;alter table public.sales_v2 enable row level security;alter table public.sale_lines_v2 enable row level security;alter table public.sale_line_batch_allocations enable row level security;alter table public.held_sales enable row level security;alter table public.payments_v2 enable row level security;alter table public.sale_returns enable row level security;alter table public.sale_return_lines enable row level security;alter table public.fiscal_documents enable row level security;alter table public.fiscal_attempts enable row level security;
create policy shifts_v2_select on public.shifts_v2 for select to authenticated using(public.v2_has_permission(organization_id,'sales.view',branch_id)or public.v2_has_support_grant(organization_id,'sales.view'));
create policy shift_totals_select on public.shift_totals for select to authenticated using(exists(select 1 from public.shifts_v2 s where s.id=shift_id and(public.v2_has_permission(s.organization_id,'sales.view',s.branch_id)or public.v2_has_support_grant(s.organization_id,'sales.view'))));
create policy sales_v2_select on public.sales_v2 for select to authenticated using(public.v2_can_view_sale(organization_id,branch_id,shift_id,false));
create policy sale_lines_v2_cost_select on public.sale_lines_v2 for select to authenticated using(exists(select 1 from public.sales_v2 s where s.id=sale_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.shift_id,true)));
create policy sale_allocations_cost_select on public.sale_line_batch_allocations for select to authenticated using(exists(select 1 from public.sale_lines_v2 l join public.sales_v2 s on s.id=l.sale_id where l.id=sale_line_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.shift_id,true)));
create policy held_sales_select on public.held_sales for select to authenticated using(public.v2_has_permission(organization_id,'sales.post',branch_id)and(created_by=public.v2_current_membership_id(organization_id)or exists(select 1 from public.organization_memberships m where m.id=public.v2_current_membership_id(organization_id)and m.system_role='owner')));
create policy payments_v2_select on public.payments_v2 for select to authenticated using(exists(select 1 from public.shifts_v2 s where s.id=shift_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.id,false)));
create policy sale_returns_select on public.sale_returns for select to authenticated using(exists(select 1 from public.sales_v2 s where s.id=original_sale_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.shift_id,false)));
create policy return_lines_select on public.sale_return_lines for select to authenticated using(exists(select 1 from public.sale_returns r join public.sales_v2 s on s.id=r.original_sale_id where r.id=sale_return_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.shift_id,false)));
create policy fiscal_documents_select on public.fiscal_documents for select to authenticated using(exists(select 1 from public.shifts_v2 s where s.id=shift_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.id,false)));
create policy fiscal_attempts_select on public.fiscal_attempts for select to authenticated using(exists(select 1 from public.fiscal_documents f join public.organization_memberships m on m.id=public.v2_current_membership_id(f.organization_id)where f.id=fiscal_document_id and(m.system_role='owner'or public.v2_has_support_grant(f.organization_id,'sales.view'))));
create trigger v2_held_sales_context before insert or update or delete on public.held_sales for each row execute function public.v2_sales_context_required();

create or replace function public.v2_sales_journal(o uuid,b uuid default null)returns table(id uuid,branch_id uuid,register_id uuid,shift_id uuid,customer_counterparty_id uuid,document_number text,business_date date,status text,currency_code char(3),subtotal_amount numeric,discount_amount numeric,total_amount numeric,paid_amount numeric,created_at timestamptz)language sql stable security definer set search_path=''as $$select s.id,s.branch_id,s.register_id,s.shift_id,s.customer_counterparty_id,s.document_number,s.business_date,s.status,s.currency_code,s.subtotal_amount,s.discount_amount,s.total_amount,s.paid_amount,s.created_at from public.sales_v2 s where s.organization_id=o and(b is null or s.branch_id=b)and public.v2_can_view_sale(o,s.branch_id,s.shift_id,false)$$;
create or replace function public.v2_sale_lines_redacted(sale uuid)returns table(id uuid,line_number integer,product_id uuid,product_name_snapshot text,unit_id uuid,unit_name_snapshot text,quantity numeric,unit_factor numeric,base_quantity numeric,unit_sale_price numeric,discount_amount numeric,tax_amount numeric,line_total_amount numeric)language sql stable security definer set search_path=''as $$select l.id,l.line_number,l.product_id,l.product_name_snapshot,l.unit_id,l.unit_name_snapshot,l.quantity,l.unit_factor,l.base_quantity,l.unit_sale_price,l.discount_amount,l.tax_amount,l.line_total_amount from public.sale_lines_v2 l join public.sales_v2 s on s.id=l.sale_id where l.sale_id=sale and public.v2_can_view_sale(s.organization_id,s.branch_id,s.shift_id,false)$$;

revoke all on public.shifts_v2,public.shift_totals,public.sales_v2,public.sale_lines_v2,public.sale_line_batch_allocations,public.held_sales,public.payments_v2,public.sale_returns,public.sale_return_lines,public.fiscal_documents,public.fiscal_attempts from anon,authenticated;
grant select on public.shifts_v2,public.shift_totals,public.sales_v2,public.sale_lines_v2,public.sale_line_batch_allocations,public.held_sales,public.payments_v2,public.sale_returns,public.sale_return_lines,public.fiscal_documents,public.fiscal_attempts to authenticated;

-- Commands ------------------------------------------------------------------
create or replace function public.v2_require_open_sales_shift(o uuid,b uuid,r uuid,sh uuid,d uuid,a uuid)returns public.shifts_v2 language plpgsql security definer set search_path=''as $$
declare x public.shifts_v2%rowtype;m public.organization_memberships%rowtype;
begin
 select * into x from public.shifts_v2 where id=sh for update;
 if not found or x.status<>'open'or x.organization_id<>o or x.branch_id<>b or x.register_id<>r then raise exception using errcode='P0001',message='V2_SALE_OPEN_SHIFT_REQUIRED';end if;
 if not exists(select 1 from public.registers q where q.id=r and q.organization_id=o and q.branch_id=b and q.status='active')then raise exception using errcode='P0001',message='V2_SALE_OPEN_SHIFT_REQUIRED';end if;
 if not exists(select 1 from public.devices_v2 q where q.id=d and q.organization_id=o and q.branch_id=b and q.register_id=r and q.status='trusted')then raise exception using errcode='P0001',message='V2_SHIFT_DEVICE_SCOPE_MISMATCH';end if;
 select * into m from public.organization_memberships where id=a and organization_id=o and status='active';if not found then raise exception using errcode='P0001',message='V2_SHIFT_NOT_OWNED';end if;
 if m.system_role='seller'and x.opened_by<>a then raise exception using errcode='P0001',message='V2_SHIFT_NOT_OWNED';end if;
 if m.system_role='owner'and not public.v2_can_access_branch(o,b)then raise exception using errcode='P0001',message='V2_SHIFT_NOT_OWNED';end if;
 return x;
end$$;

create or replace function public.v2_recompute_sale_return_status(sale uuid)returns text language plpgsql security definer set search_path=''as $$
declare sold numeric;returned numeric;next_status text;
begin
 select coalesce(sum(base_quantity),0)into sold from public.sale_lines_v2 where sale_id=sale;
 select coalesce(sum(rli.quantity),0)into returned from public.sale_return_lines rli join public.sale_returns sr on sr.id=rli.sale_return_id where sr.original_sale_id=sale and sr.status='posted'and sr.reversal_of_id is null;
 next_status:=case when returned=0 then'posted'when returned>=sold then'returned'else'partially_returned'end;
 perform set_config('market_pos.sale_lifecycle_command','on',true);update public.sales_v2 set status=next_status where id=sale;perform set_config('market_pos.sale_lifecycle_command','off',true);return next_status;
end$$;

create or replace function public.v2_open_shift(o uuid,b uuid,r uuid,d uuid,opening numeric,op uuid)returns uuid language plpgsql security definer set search_path=''as $$
declare a uuid:=public.v2_current_membership_id(o);i uuid:=gen_random_uuid();c uuid;p jsonb:=jsonb_build_object('organization_id',o,'branch_id',b,'register_id',r,'device_id',d,'opening_cash_amount',opening);begin
 if not public.v2_has_permission(o,'shifts.open',b)then raise exception using errcode='P0001',message='V2_SHIFT_OPEN_REQUIRED';end if;if not exists(select 1 from public.devices_v2 x where x.id=d and x.organization_id=o and x.branch_id=b and x.register_id=r and x.status='trusted')then raise exception using errcode='P0001',message='V2_SHIFT_DEVICE_SCOPE_MISMATCH';end if;
 c:=public.v2_begin_inventory_command(o,b,d,op,'shift.open',p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;
 perform pg_advisory_xact_lock(hashtextextended('shift:'||r::text,0));if exists(select 1 from public.shifts_v2 where register_id=r and status in('open','closing'))then raise exception using errcode='P0001',message='V2_SHIFT_ALREADY_OPEN';end if;
 perform set_config('market_pos.sales_command','on',true);insert into public.shifts_v2(id,organization_id,branch_id,register_id,opened_by,opening_cash_amount)values(i,o,b,r,a,opening);insert into public.shift_totals(organization_id,shift_id,payment_method)values(o,i,'cash'),(o,i,'card'),(o,i,'transfer');perform public.v2_emit_domain_event(o,b,d,a,c,null,'shift',i,'shift.opened','ShiftOpened',p);perform public.v2_complete_inventory_command(c,'shift',i,jsonb_build_object('id',i,'status','open'));perform set_config('market_pos.sales_command','off',true);return i;end$$;

create or replace function public.v2_close_shift(i uuid,d uuid,actual numeric,op uuid)returns uuid language plpgsql security definer set search_path=''as $$
declare s public.shifts_v2%rowtype;a uuid;c uuid;p jsonb;cash_expected numeric;cash_projection numeric;begin select * into s from public.shifts_v2 where id=i for update;if not found then raise exception using errcode='P0001',message='V2_SHIFT_NOT_FOUND';end if;if not public.v2_has_permission(s.organization_id,'shifts.close',s.branch_id)then raise exception using errcode='P0001',message='V2_SHIFT_CLOSE_REQUIRED';end if;a:=public.v2_current_membership_id(s.organization_id);if exists(select 1 from public.organization_memberships where id=a and system_role='seller')and a<>s.opened_by then raise exception using errcode='P0001',message='V2_SHIFT_NOT_OWNED';end if;if actual<0 then raise exception using errcode='P0001',message='V2_SHIFT_ACTUAL_CASH_INVALID';end if;if not exists(select 1 from public.devices_v2 q where q.id=d and q.organization_id=s.organization_id and q.branch_id=s.branch_id and q.register_id=s.register_id and q.status='trusted')then raise exception using errcode='P0001',message='V2_SHIFT_DEVICE_SCOPE_MISMATCH';end if;p:=jsonb_build_object('shift_id',i,'actual_cash_amount',actual,'device_id',d);c:=public.v2_begin_inventory_command(s.organization_id,s.branch_id,d,op,'shift.close',p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;if s.status<>'open'then raise exception using errcode='P0001',message='V2_SHIFT_NOT_OPEN';end if;
 perform 1 from public.shift_totals where shift_id=i order by payment_method for update;select coalesce(sum(amount),0)into cash_expected from public.payments_v2 where shift_id=i and method='cash'and status='confirmed';select expected_amount into cash_projection from public.shift_totals where shift_id=i and payment_method='cash';if cash_projection<>cash_expected or exists(select 1 from public.shift_totals t where t.shift_id=i and t.expected_amount<>(select coalesce(sum(p.amount),0)from public.payments_v2 p where p.shift_id=i and p.method=t.payment_method and p.status='confirmed'))then raise exception using errcode='P0001',message='V2_SHIFT_TOTAL_PROJECTION_DRIFT';end if;
 perform set_config('market_pos.sales_command','on',true);update public.shift_totals set actual_amount=case when payment_method='cash'then actual-s.opening_cash_amount else null end,version=version+1,updated_at=now()where shift_id=i;update public.shifts_v2 set status='closed',closed_by=a,closed_at=clock_timestamp(),actual_cash_amount=actual,difference_amount=(actual-s.opening_cash_amount)-cash_expected,version=version+1 where id=i;perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,null,'shift',i,'shift.closed','ShiftClosed',p);perform public.v2_complete_inventory_command(c,'shift',i,jsonb_build_object('id',i,'status','closed'));perform set_config('market_pos.sales_command','off',true);return i;end$$;

create or replace function public.v2_hold_sale(i uuid,o uuid,b uuid,r uuid,cart jsonb,expires timestamptz,op uuid)returns uuid language plpgsql security definer set search_path=''as $$
declare a uuid:=public.v2_current_membership_id(o);x public.held_sales%rowtype;z uuid:=coalesce(i,gen_random_uuid());c uuid;p jsonb:=jsonb_build_object('held_sale_id',i,'register_id',r,'cart',cart,'expires_at',expires);begin if not public.v2_has_permission(o,'sales.post',b)then raise exception using errcode='P0001',message='V2_SALES_POST_REQUIRED';end if;c:=public.v2_begin_inventory_command(o,b,null,op,case when i is null then'held_sale.create'else'held_sale.update'end,p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;if not exists(select 1 from public.registers q where q.id=r and q.organization_id=o and q.branch_id=b and q.status='active')then raise exception using errcode='P0001',message='V2_HELD_SALE_SCOPE_MISMATCH';end if;perform set_config('market_pos.sales_command','on',true);if i is null then insert into public.held_sales(id,organization_id,branch_id,register_id,created_by,cart_payload,expires_at)values(z,o,b,r,a,cart,expires);else select * into x from public.held_sales where id=i for update;if not found then raise exception using errcode='P0001',message='V2_HELD_SALE_NOT_FOUND';end if;if x.organization_id<>o or x.branch_id<>b or x.register_id<>r or(x.created_by<>a and not exists(select 1 from public.organization_memberships m where m.id=a and m.system_role='owner'))then raise exception using errcode='P0001',message='V2_HELD_SALE_SCOPE_MISMATCH';end if;update public.held_sales set cart_payload=cart,expires_at=expires,updated_at=now()where id=i;end if;perform public.v2_emit_domain_event(o,b,null,a,c,null,'held_sale',z,'held_sale.changed','HeldSaleChanged',p);perform public.v2_complete_inventory_command(c,'held_sale',z,jsonb_build_object('id',z));perform set_config('market_pos.sales_command','off',true);return z;end$$;
create or replace function public.v2_update_held_sale(i uuid,o uuid,b uuid,r uuid,cart jsonb,expires timestamptz,op uuid)returns uuid language sql set search_path=''as $$select public.v2_hold_sale(i,o,b,r,cart,expires,op)$$;
create or replace function public.v2_delete_held_sale(i uuid,op uuid)returns uuid language plpgsql security definer set search_path=''as $$declare x public.held_sales%rowtype;a uuid;c uuid;p jsonb;begin select * into x from public.held_sales where id=i for update;if not found then raise exception using errcode='P0001',message='V2_HELD_SALE_NOT_FOUND';end if;a:=public.v2_current_membership_id(x.organization_id);if x.created_by<>a and not exists(select 1 from public.organization_memberships where id=a and system_role='owner')and x.expires_at>now()then raise exception using errcode='P0001',message='V2_HELD_SALE_SCOPE_MISMATCH';end if;p:=jsonb_build_object('held_sale_id',i);c:=public.v2_begin_inventory_command(x.organization_id,x.branch_id,null,op,'held_sale.delete',p);if(select status='succeeded'from public.command_log where id=c)then return i;end if;perform set_config('market_pos.sales_command','on',true);delete from public.held_sales where id=i;perform public.v2_emit_domain_event(x.organization_id,x.branch_id,null,a,c,null,'held_sale',i,'held_sale.changed','HeldSaleChanged',p);perform public.v2_complete_inventory_command(c,'held_sale',i,jsonb_build_object('id',i,'deleted',true));perform set_config('market_pos.sales_command','off',true);return i;end$$;

create or replace function public.v2_create_fiscal_intent(o uuid,b uuid,r uuid,s uuid,sale uuid,ret uuid,key text,c uuid,a uuid)returns uuid language plpgsql security definer set search_path=''as $$declare all_settings jsonb;cfg jsonb;mode text;provider text;i uuid;begin select settings into all_settings from public.registers where id=r;if not public.v2_fiscal_settings_valid(all_settings)then raise exception using errcode='P0001',message='V2_FISCAL_SETTINGS_INVALID';end if;cfg:=all_settings->'fiscal';mode:=coalesce(cfg->>'mode','disabled');if mode='disabled'then return null;end if;provider:=cfg->>'provider_code';i:=gen_random_uuid();insert into public.fiscal_documents(id,organization_id,branch_id,register_id,shift_id,sale_id,sale_return_id,provider_code,status,idempotency_key)values(i,o,b,r,s,sale,ret,provider,case when mode='required'then'pending'else'deferred'end,key);perform public.v2_emit_domain_event(o,b,null,a,c,null,'fiscal_document',i,'fiscalization.requested',case when mode='required'then'FiscalizationRequested'else'FiscalizationDeferred'end,jsonb_build_object('fiscal_document_id',i));return i;end$$;

create or replace function public.v2_post_sale(o uuid,b uuid,r uuid,w uuid,sh uuid,customer uuid,n text,bd date,cur char(3),d uuid,op uuid,client_at timestamptz,lines jsonb,pays jsonb,approval uuid default null)returns uuid language plpgsql security definer set search_path=''as $$
declare i uuid:=gen_random_uuid();a uuid:=public.v2_current_membership_id(o);c uuid;p jsonb:=jsonb_build_object('organization_id',o,'branch_id',b,'register_id',r,'warehouse_id',w,'shift_id',sh,'customer_id',customer,'document_number',n,'business_date',bd,'currency_code',cur,'device_id',d,'client_created_at',client_at,'lines',lines,'payments',pays);x public.shifts_v2%rowtype;pl uuid;ln jsonb;pay jsonb;line_id uuid;alloc_id uuid;movement_id uuid;prod uuid;unit uuid;price_id uuid;effective timestamptz;q numeric;factor numeric;base numeric;price numeric;disc numeric;line_total numeric;subtotal numeric:=0;discount numeric:=0;total numeric;paid numeric:=0;limit_ numeric;remaining numeric;take numeric;cost_sum numeric;batch record;begin
 if not public.v2_has_permission(o,'sales.post',b)then raise exception using errcode='P0001',message='V2_SALES_POST_REQUIRED';end if;c:=public.v2_begin_inventory_command(o,b,d,op,'sale.post',p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;
 x:=public.v2_require_open_sales_shift(o,b,r,sh,d,a);if not exists(select 1 from public.warehouses z where z.id=w and z.organization_id=o and z.branch_id=b)then raise exception using errcode='P0001',message='V2_SALE_LOCATION_SCOPE_MISMATCH';end if;
 select id into pl from public.price_lists where organization_id=o and status='active'and is_default and(branch_id=b or branch_id is null)order by(branch_id is not null)desc limit 1;if pl is null then raise exception using errcode='P0001',message='V2_SALE_PRICE_NOT_FOUND';end if;if(select currency_code from public.price_lists where id=pl)<>cur then raise exception using errcode='P0001',message='V2_SALE_PRICE_STALE';end if;if jsonb_typeof(lines)<>'array'or jsonb_array_length(lines)=0 then raise exception using errcode='P0001',message='V2_SALE_LINES_REQUIRED';end if;
 for ln in select value from jsonb_array_elements(lines)loop prod:=(ln->>'product_id')::uuid;unit:=(ln->>'unit_id')::uuid;price_id:=(ln->>'product_price_id')::uuid;effective:=(ln->>'effective_at')::timestamptz;q:=(ln->>'quantity')::numeric;factor:=(ln->>'unit_factor')::numeric;base:=q*factor;price:=(ln->>'unit_sale_price')::numeric;disc:=coalesce((ln->>'discount_amount')::numeric,0);if coalesce((ln->>'tax_amount')::numeric,0)<>0 then raise exception using errcode='P0001',message='V2_SALE_TAX_NOT_CONFIGURED';end if;if not exists(select 1 from public.product_prices pp where pp.id=price_id and pp.organization_id=o and pp.product_id=prod and pp.price_list_id=pl and pp.currency_code=cur and pp.amount=price and effective>=pp.valid_from and(pp.valid_to is null or effective<pp.valid_to))then if exists(select 1 from public.product_prices where id=price_id)then raise exception using errcode='P0001',message='V2_SALE_PRICE_STALE';else raise exception using errcode='P0001',message='V2_SALE_PRICE_NOT_FOUND';end if;end if;line_total:=round(q*price-disc,4);if line_total<0 then raise exception using errcode='P0001',message='V2_SALE_DISCOUNT_LIMIT_EXCEEDED';end if;subtotal:=subtotal+round(q*price,4);discount:=discount+disc;end loop;total:=subtotal-discount;
