create or replace function public.v2_reverse_sale_return(ret uuid,n text,d uuid,op uuid,approval uuid,payload jsonb default'{}')returns uuid language plpgsql security definer set search_path=''as $$
declare sr public.sale_returns%rowtype;s public.sales_v2%rowtype;r uuid:=gen_random_uuid();a uuid;c uuid;p jsonb:=payload||jsonb_build_object('sale_return_id',ret,'document_number',n);rl public.sale_return_lines%rowtype;nr uuid;m public.inventory_movements%rowtype;nm uuid;begin select * into sr from public.sale_returns where id=ret for update;if not found then raise exception using errcode='P0001',message='V2_SALE_RETURN_NOT_FOUND';end if;select * into s from public.sales_v2 where id=sr.original_sale_id for update;if not public.v2_has_permission(sr.organization_id,'sales.reverse',s.branch_id)then raise exception using errcode='P0001',message='V2_SALE_REVERSE_REQUIRED';end if;a:=public.v2_current_membership_id(sr.organization_id);c:=public.v2_use_approved_command(approval,sr.organization_id,'sales.reverse',op,p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;if sr.status='reversed'or exists(select 1 from public.sale_returns where reversal_of_id=ret)then raise exception using errcode='P0001',message='V2_SALE_RETURN_ALREADY_REVERSED';end if;perform set_config('market_pos.sales_command','on',true);perform set_config('market_pos.inventory_command','on',true);insert into public.sale_returns(id,organization_id,original_sale_id,register_id,shift_id,document_number,total_amount,device_id,local_operation_id,posted_by,reversal_of_id)values(r,sr.organization_id,sr.original_sale_id,sr.register_id,sr.shift_id,n,sr.total_amount,d,op,a,ret);for rl in select * from public.sale_return_lines where sale_return_id=ret loop nr:=gen_random_uuid();insert into public.sale_return_lines(id,organization_id,sale_return_id,original_sale_line_id,quantity,refund_amount)values(nr,sr.organization_id,r,rl.original_sale_line_id,rl.quantity,rl.refund_amount);for m in select * from public.inventory_movements where source_document_type='sale_return'and source_line_id=rl.id and quantity_delta>0 loop nm:=gen_random_uuid();insert into public.inventory_movements(id,organization_id,branch_id,warehouse_id,product_id,batch_id,movement_type,quantity_delta,source_document_type,source_document_id,source_line_id,movement_role,reversal_of_id,command_id,created_by)values(nm,m.organization_id,m.branch_id,m.warehouse_id,m.product_id,m.batch_id,'sale_return_reversal',-m.quantity_delta,'sale_return',r,nr,'reversal',m.id,c,a);update public.inventory_balances set on_hand_quantity=on_hand_quantity-m.quantity_delta,last_movement_id=nm,version=version+1 where warehouse_id=m.warehouse_id and product_id=m.product_id and(batch_id=m.batch_id or batch_id is null);end loop;end loop;update public.sale_returns set status='reversed'where id=ret;update public.sales_v2 set status=case when exists(select 1 from public.sale_returns where original_sale_id=s.id and status='posted')then'partially_returned'else'posted'end where id=s.id;perform public.v2_emit_domain_event(sr.organization_id,s.branch_id,d,a,c,approval,'sale_return',r,'sale_return.reversed','SaleReturnReversed',jsonb_build_object('original_id',ret,'reversal_id',r));perform public.v2_complete_inventory_command(c,'sale_return',r,jsonb_build_object('id',r));perform set_config('market_pos.inventory_command','off',true);perform set_config('market_pos.sales_command','off',true);return r;end$$;

create or replace function public.v2_begin_fiscal_attempt(i uuid)returns table(processing_token uuid,attempt_number integer)language plpgsql security definer set search_path=''as $$declare f public.fiscal_documents%rowtype;t uuid:=gen_random_uuid();n integer;begin select * into f from public.fiscal_documents where id=i for update;if not found or f.status not in('pending','failed','deferred')then raise exception using errcode='P0001',message='V2_FISCAL_NOT_RETRYABLE';end if;select coalesce(max(a.attempt_number),0)+1 into n from public.fiscal_attempts a where a.fiscal_document_id=i;perform set_config('market_pos.sales_command','on',true);update public.fiscal_documents set status='processing',processing_token=t,processing_started_at=clock_timestamp(),updated_at=now()where id=i;perform set_config('market_pos.sales_command','off',true);return query select t,n;end$$;
-- Re-declare with qualified references so worker replay remains unambiguous to
-- PL/pgSQL even though the public API keeps its documented parameter names.
create or replace function public.v2_complete_fiscal_attempt(i uuid,t uuid,n integer,outcome text,request_hash text,response_code text default null,response_payload jsonb default null,error_code text default null)returns uuid language plpgsql security definer set search_path=''as $$
declare f public.fiscal_documents%rowtype;a uuid;ev text;
begin
 select * into f from public.fiscal_documents fd where fd.id=i for update;
 if not found or f.status<>'processing'or f.processing_token<>t then
  if exists(select 1 from public.fiscal_attempts fa where fa.fiscal_document_id=i and fa.attempt_number=n and fa.request_hash=$5)then return(select fa.id from public.fiscal_attempts fa where fa.fiscal_document_id=i and fa.attempt_number=n and fa.request_hash=$5);end if;
  raise exception using errcode='P0001',message='V2_FISCAL_PROCESSING_TOKEN_MISMATCH';
 end if;
 if outcome not in('issued','failed','deferred')then raise exception using errcode='P0001',message='V2_FISCAL_OUTCOME_INVALID';end if;
 a:=gen_random_uuid();perform set_config('market_pos.sales_command','on',true);
 insert into public.fiscal_attempts(id,organization_id,fiscal_document_id,attempt_number,request_hash,outcome,response_code,response_payload,error_code)values(a,f.organization_id,i,n,$5,outcome,response_code,response_payload,error_code);
 update public.fiscal_documents set status=outcome,external_receipt_id=case when outcome='issued'then response_code else external_receipt_id end,issued_at=case when outcome='issued'then clock_timestamp()else null end,processing_token=null,processing_started_at=null,updated_at=now()where id=i;
 ev:=case outcome when'issued'then'FiscalizationCompleted'when'failed'then'FiscalizationFailed'else'FiscalizationDeferred'end;
 insert into public.outbox_events(organization_id,aggregate_type,aggregate_id,event_type,payload)values(f.organization_id,'fiscal_document',i,ev,jsonb_build_object('fiscal_document_id',i,'attempt_number',n));
 perform set_config('market_pos.sales_command','off',true);return a;
end$$;

