revoke execute on function public.v2_effective_discount_limit(uuid),public.v2_can_view_sale(uuid,uuid,uuid,boolean),public.v2_sales_context_required(),public.v2_sales_append_only(),public.v2_shift_guard(),public.v2_shift_total_guard(),public.v2_sale_graph_guard(),public.v2_payment_guard(),public.v2_fiscal_document_guard(),public.v2_create_fiscal_intent(uuid,uuid,uuid,uuid,uuid,uuid,text,uuid,uuid)from public,anon,authenticated;
revoke execute on function public.v2_sales_journal(uuid,uuid),public.v2_sale_lines_redacted(uuid),public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,uuid),public.v2_close_shift(uuid,uuid,numeric,uuid),public.v2_hold_sale(uuid,uuid,uuid,uuid,jsonb,timestamptz,uuid),public.v2_update_held_sale(uuid,uuid,uuid,uuid,jsonb,timestamptz,uuid),public.v2_delete_held_sale(uuid,uuid),public.v2_post_sale(uuid,uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamptz,jsonb,jsonb,uuid),public.v2_post_sale_return(uuid,uuid,text,uuid,uuid,jsonb,jsonb),public.v2_reverse_sale(uuid,text,uuid,uuid,uuid,jsonb),public.v2_reverse_sale_return(uuid,text,uuid,uuid,uuid,jsonb)from public,anon;
grant execute on function public.v2_sales_journal(uuid,uuid),public.v2_sale_lines_redacted(uuid),public.v2_open_shift(uuid,uuid,uuid,uuid,numeric,uuid),public.v2_close_shift(uuid,uuid,numeric,uuid),public.v2_hold_sale(uuid,uuid,uuid,uuid,jsonb,timestamptz,uuid),public.v2_update_held_sale(uuid,uuid,uuid,uuid,jsonb,timestamptz,uuid),public.v2_delete_held_sale(uuid,uuid),public.v2_post_sale(uuid,uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamptz,jsonb,jsonb,uuid),public.v2_post_sale_return(uuid,uuid,text,uuid,uuid,jsonb,jsonb),public.v2_reverse_sale(uuid,text,uuid,uuid,uuid,jsonb),public.v2_reverse_sale_return(uuid,text,uuid,uuid,uuid,jsonb)to authenticated;
grant execute on function public.v2_can_view_sale(uuid,uuid,uuid,boolean)to authenticated;
revoke execute on function public.v2_begin_fiscal_attempt(uuid),public.v2_complete_fiscal_attempt(uuid,uuid,integer,text,text,text,jsonb,text)from public,anon,authenticated;grant execute on function public.v2_begin_fiscal_attempt(uuid),public.v2_complete_fiscal_attempt(uuid,uuid,integer,text,text,text,jsonb,text)to service_role;

-- Review hardening: current-shift reversals, strict lifecycle and fiscal worker.
alter table public.fiscal_attempts add column processing_token uuid not null;
alter table public.fiscal_attempts add column completion_hash text not null;

create or replace function public.v2_can_view_shift(o uuid,b uuid,sh uuid)returns boolean language sql stable security definer set search_path=''as $$
 select (public.v2_has_permission(o,'sales.view',b)and exists(select 1 from public.organization_memberships m join public.user_profiles u on u.id=m.user_profile_id where m.id=public.v2_current_membership_id(o)and m.status='active'and u.status='active'and(m.system_role='owner'or(m.system_role='seller'and exists(select 1 from public.shifts_v2 s where s.id=sh and s.opened_by=m.id)))))or public.v2_has_support_grant(o,'sales.view')
$$;

drop policy shifts_v2_select on public.shifts_v2;create policy shifts_v2_select on public.shifts_v2 for select to authenticated using(public.v2_can_view_shift(organization_id,branch_id,id));
drop policy shift_totals_select on public.shift_totals;create policy shift_totals_select on public.shift_totals for select to authenticated using(exists(select 1 from public.shifts_v2 s where s.id=shift_id and public.v2_can_view_shift(s.organization_id,s.branch_id,s.id)));
drop policy fiscal_documents_select on public.fiscal_documents;create policy fiscal_documents_select on public.fiscal_documents for select to authenticated using((public.v2_has_permission(organization_id,'sales.view',branch_id)and exists(select 1 from public.organization_memberships m where m.id=public.v2_current_membership_id(organization_id)and m.system_role='owner'and m.status='active'))or public.v2_has_support_grant(organization_id,'sales.view'));

create or replace function public.v2_fiscal_status_for_sale(source_id uuid)returns table(fiscal_document_id uuid,sale_id uuid,status text,issued_at timestamptz,created_at timestamptz,updated_at timestamptz)language sql stable security definer set search_path=''as $$select f.id,f.sale_id,f.status,f.issued_at,f.created_at,f.updated_at from public.fiscal_documents f join public.sales_v2 s on s.id=f.sale_id where f.sale_id=source_id and public.v2_can_view_sale(s.organization_id,s.branch_id,s.shift_id,false)$$;
create or replace function public.v2_fiscal_status_for_return(source_id uuid)returns table(fiscal_document_id uuid,sale_return_id uuid,status text,issued_at timestamptz,created_at timestamptz,updated_at timestamptz)language sql stable security definer set search_path=''as $$select f.id,f.sale_return_id,f.status,f.issued_at,f.created_at,f.updated_at from public.fiscal_documents f join public.sale_returns r on r.id=f.sale_return_id join public.sales_v2 s on s.id=r.original_sale_id where f.sale_return_id=source_id and public.v2_can_view_sale(s.organization_id,s.branch_id,r.shift_id,false)$$;

create or replace function public.v2_strict_financial_immutable()returns trigger language plpgsql set search_path=''as $$begin raise exception using errcode='P0001',message='V2_SALES_APPEND_ONLY';end$$;
create or replace function public.v2_sale_line_immutable()returns trigger language plpgsql set search_path=''as $$begin if tg_op='UPDATE'and coalesce(current_setting('market_pos.sale_build_command',true),'')='on'and(to_jsonb(new)-'unit_cost')=(to_jsonb(old)-'unit_cost')then return new;end if;raise exception using errcode='P0001',message='V2_SALES_APPEND_ONLY';end$$;
create or replace function public.v2_sale_return_guard()returns trigger language plpgsql set search_path=''as $$begin
 if tg_op='DELETE'then raise exception using errcode='P0001',message='V2_SALES_APPEND_ONLY';end if;
 if tg_op='INSERT'and new.reversal_of_id is not null and coalesce(current_setting('market_pos.sale_reversal_command',true),'')<>'on'then raise exception using errcode='P0001',message='V2_SALE_REVERSAL_CONTEXT_REQUIRED';end if;
 if tg_op='UPDATE'then if coalesce(current_setting('market_pos.sale_lifecycle_command',true),'')<>'on'or old.status<>'posted'or new.status<>'reversed'or(to_jsonb(new)-'status')<>(to_jsonb(old)-'status')then raise exception using errcode='P0001',message='V2_SALE_RETURN_IMMUTABLE';end if;end if;return new;
end$$;
drop trigger v2_sale_lines_append_only on public.sale_lines_v2;create trigger v2_sale_lines_append_only before update or delete on public.sale_lines_v2 for each row execute function public.v2_sale_line_immutable();
drop trigger v2_sale_allocations_append_only on public.sale_line_batch_allocations;create trigger v2_sale_allocations_append_only before update or delete on public.sale_line_batch_allocations for each row execute function public.v2_strict_financial_immutable();
drop trigger v2_payments_append_only on public.payments_v2;create trigger v2_payments_append_only before update or delete on public.payments_v2 for each row execute function public.v2_strict_financial_immutable();
drop trigger v2_return_lines_append_only on public.sale_return_lines;create trigger v2_return_lines_append_only before update or delete on public.sale_return_lines for each row execute function public.v2_strict_financial_immutable();
drop trigger v2_returns_delete on public.sale_returns;create trigger v2_returns_lifecycle before insert or update or delete on public.sale_returns for each row execute function public.v2_sale_return_guard();

-- The sale graph guard permits historical customer snapshots only for a
-- controlled reversal header; ordinary sales retain the active-role rule.
create or replace function public.v2_sale_graph_guard()returns trigger language plpgsql set search_path=''as $$
declare o uuid;b uuid;r uuid;w uuid;s uuid;original public.sales_v2%rowtype;
begin
 if tg_table_name='sales_v2'theN
  if not exists(select 1 from public.registers x where x.id=new.register_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id)or not exists(select 1 from public.warehouses x where x.id=new.warehouse_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id)or not exists(select 1 from public.devices_v2 x where x.id=new.device_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id and x.register_id=new.register_id and x.status='trusted')or not exists(select 1 from public.shifts_v2 x where x.id=new.shift_id and x.organization_id=new.organization_id and x.branch_id=new.branch_id and x.register_id=new.register_id)then raise exception using errcode='P0001',message='V2_SALE_LOCATION_SCOPE_MISMATCH';end if;
  if new.reversal_of_id is not null then if coalesce(current_setting('market_pos.sale_reversal_command',true),'')<>'on'then raise exception using errcode='P0001',message='V2_SALE_REVERSAL_CONTEXT_REQUIRED';end if;select * into original from public.sales_v2 where id=new.reversal_of_id;if not found or new.organization_id<>original.organization_id or new.branch_id<>original.branch_id or new.register_id<>original.register_id or new.warehouse_id<>original.warehouse_id or new.currency_code<>original.currency_code or new.customer_counterparty_id is distinct from original.customer_counterparty_id then raise exception using errcode='P0001',message='V2_SALE_REVERSAL_SCOPE_MISMATCH';end if;
  elsif new.customer_counterparty_id is not null and not exists(select 1 from public.counterparty_roles cr where cr.counterparty_id=new.customer_counterparty_id and cr.organization_id=new.organization_id and cr.role_code='customer'and cr.ended_at is null)then raise exception using errcode='P0001',message='V2_SALE_ACTIVE_CUSTOMER_REQUIRED';end if;
  if new.debt_amount<>0 then raise exception using errcode='P0001',message='V2_SALE_DEBT_NOT_AVAILABLE_BEFORE_0015';end if;
  if tg_op='UPDATE'and((to_jsonb(new)-'status')<>(to_jsonb(old)-'status')or coalesce(current_setting('market_pos.sale_lifecycle_command',true),'')<>'on')then raise exception using errcode='P0001',message='V2_SALE_POSTED_IMMUTABLE';end if;
 elsif tg_table_name='sale_lines_v2'then select organization_id,branch_id,register_id,warehouse_id,shift_id into o,b,r,w,s from public.sales_v2 where id=new.sale_id;if o is distinct from new.organization_id then raise exception using errcode='P0001',message='V2_SALE_LINE_SCOPE_MISMATCH';end if;
 elsif tg_table_name='sale_line_batch_allocations'then select sl.organization_id,sv.warehouse_id into o,w from public.sale_lines_v2 sl join public.sales_v2 sv on sv.id=sl.sale_id where sl.id=new.sale_line_id;if o is distinct from new.organization_id or not exists(select 1 from public.product_batches_v2 pb join public.sale_lines_v2 sl on sl.id=new.sale_line_id where pb.id=new.product_batch_id and pb.organization_id=new.organization_id and pb.warehouse_id=w and pb.product_id=sl.product_id)then raise exception using errcode='P0001',message='V2_SALE_ALLOCATION_SCOPE_MISMATCH';end if;
 end if;return new;
end$$;

-- Current-shift sale reversal.
drop function public.v2_reverse_sale(uuid,text,uuid,uuid,uuid,jsonb);
create function public.v2_reverse_sale(sale uuid,sh uuid,n text,d uuid,op uuid,approval uuid,payload jsonb default'{}')returns uuid language plpgsql security definer set search_path=''as $$
declare s public.sales_v2%rowtype;x public.shifts_v2%rowtype;r uuid:=gen_random_uuid();a uuid;c uuid;p jsonb:=payload||jsonb_build_object('sale_id',sale,'shift_id',sh,'document_number',n,'device_id',d);l public.sale_lines_v2%rowtype;nl uuid;al public.sale_line_batch_allocations%rowtype;na uuid;mv uuid;pay public.payments_v2%rowtype;np uuid;scopes jsonb;
begin select * into s from public.sales_v2 where id=sale for update;if not found then raise exception using errcode='P0001',message='V2_SALE_NOT_FOUND';end if;if not public.v2_has_permission(s.organization_id,'sales.reverse',s.branch_id)then raise exception using errcode='P0001',message='V2_SALE_REVERSE_REQUIRED';end if;a:=public.v2_current_membership_id(s.organization_id);c:=public.v2_use_approved_command(approval,s.organization_id,'sales.reverse',op,p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;x:=public.v2_require_open_sales_shift(s.organization_id,s.branch_id,s.register_id,sh,d,a);if exists(select 1 from public.sale_returns where original_sale_id=sale and status='posted'and reversal_of_id is null)then raise exception using errcode='P0001',message='V2_SALE_REVERSAL_RETURN_EXISTS';end if;if exists(select 1 from public.sales_v2 where reversal_of_id=sale)or s.status='reversed'then raise exception using errcode='P0001',message='V2_SALE_ALREADY_REVERSED';end if;
 select jsonb_agg(jsonb_build_object('warehouse_id',s.warehouse_id,'product_id',q.product_id,'batch_id',q.batch_id)order by q.product_id,q.batch_id nulls first)into scopes from(select distinct scope_line.product_id,scope_allocation.product_batch_id batch_id from public.sale_lines_v2 scope_line join public.sale_line_batch_allocations scope_allocation on scope_allocation.sale_line_id=scope_line.id where scope_line.sale_id=sale union select distinct scope_line.product_id,null::uuid from public.sale_lines_v2 scope_line where scope_line.sale_id=sale)q;perform public.v2_lock_inventory_scopes(s.organization_id,scopes);
 perform set_config('market_pos.sales_command','on',true);perform set_config('market_pos.sale_reversal_command','on',true);perform set_config('market_pos.sale_build_command','on',true);perform set_config('market_pos.inventory_command','on',true);
 insert into public.sales_v2(id,organization_id,branch_id,register_id,warehouse_id,shift_id,customer_counterparty_id,document_number,business_date,currency_code,subtotal_amount,discount_amount,tax_amount,total_amount,paid_amount,debt_amount,device_id,local_operation_id,client_created_at,posted_by,reversal_of_id)values(r,s.organization_id,s.branch_id,s.register_id,s.warehouse_id,sh,s.customer_counterparty_id,n,current_date,s.currency_code,s.subtotal_amount,s.discount_amount,0,s.total_amount,s.paid_amount,0,d,op,clock_timestamp(),a,sale);
 for l in select * from public.sale_lines_v2 where sale_id=sale order by line_number loop nl:=gen_random_uuid();insert into public.sale_lines_v2(id,organization_id,sale_id,line_number,product_id,product_name_snapshot,unit_id,unit_name_snapshot,product_price_id,quantity,unit_factor,base_quantity,unit_sale_price,unit_cost,discount_amount,tax_amount,line_total_amount)values(nl,l.organization_id,r,l.line_number,l.product_id,l.product_name_snapshot,l.unit_id,l.unit_name_snapshot,l.product_price_id,l.quantity,l.unit_factor,l.base_quantity,l.unit_sale_price,l.unit_cost,l.discount_amount,0,l.line_total_amount);for al in select * from public.sale_line_batch_allocations where sale_line_id=l.id loop na:=gen_random_uuid();mv:=gen_random_uuid();insert into public.sale_line_batch_allocations(id,organization_id,sale_line_id,product_batch_id,quantity,unit_cost,inventory_movement_id)values(na,s.organization_id,nl,al.product_batch_id,al.quantity,al.unit_cost,mv);insert into public.inventory_movements(id,organization_id,branch_id,warehouse_id,product_id,batch_id,movement_type,quantity_delta,source_document_type,source_document_id,source_line_id,movement_role,reversal_of_id,command_id,created_by)values(mv,s.organization_id,s.branch_id,s.warehouse_id,l.product_id,al.product_batch_id,'sale_reversal',al.quantity,'sale',r,na,'reversal',al.inventory_movement_id,c,a);update public.inventory_balances set on_hand_quantity=on_hand_quantity+al.quantity,last_movement_id=mv,version=version+1 where warehouse_id=s.warehouse_id and product_id=l.product_id and(batch_id=al.product_batch_id or batch_id is null);end loop;end loop;
 for pay in select * from public.payments_v2 where sale_id=sale and reversal_of_id is null loop np:=gen_random_uuid();insert into public.payments_v2(id,organization_id,branch_id,register_id,shift_id,sale_id,method,amount,currency_code,device_id,local_operation_id,reversal_of_id,created_by)values(np,s.organization_id,s.branch_id,s.register_id,sh,r,pay.method,-pay.amount,pay.currency_code,d,gen_random_uuid(),pay.id,a);update public.shift_totals set expected_amount=expected_amount-pay.amount,version=version+1,updated_at=now()where shift_id=sh and payment_method=pay.method;perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,approval,'payment',np,'payment.reversed','PaymentRefunded',jsonb_build_object('reversal_of_id',pay.id,'sale_id',r));end loop;
 perform set_config('market_pos.sale_lifecycle_command','on',true);update public.sales_v2 set status='reversed'where id=sale;perform set_config('market_pos.sale_lifecycle_command','off',true);perform public.v2_create_fiscal_intent(s.organization_id,s.branch_id,s.register_id,sh,r,null,op::text,c,a);perform public.v2_emit_domain_event(s.organization_id,s.branch_id,d,a,c,approval,'sale',r,'sale.reversed','SaleReversed',jsonb_build_object('original_id',sale,'reversal_id',r));perform public.v2_complete_inventory_command(c,'sale',r,jsonb_build_object('id',r,'status','posted'));perform set_config('market_pos.inventory_command','off',true);perform set_config('market_pos.sale_build_command','off',true);perform set_config('market_pos.sale_reversal_command','off',true);perform set_config('market_pos.sales_command','off',true);return r;
end$$;

-- Current-shift return reversal with complete payment/fiscal graph.
drop function public.v2_reverse_sale_return(uuid,text,uuid,uuid,uuid,jsonb);
create function public.v2_reverse_sale_return(ret uuid,sh uuid,n text,d uuid,op uuid,approval uuid,payload jsonb default'{}')returns uuid language plpgsql security definer set search_path=''as $$
declare sr public.sale_returns%rowtype;s public.sales_v2%rowtype;x public.shifts_v2%rowtype;r uuid:=gen_random_uuid();a uuid;c uuid;p jsonb:=payload||jsonb_build_object('sale_return_id',ret,'shift_id',sh,'document_number',n,'device_id',d);rl public.sale_return_lines%rowtype;nr uuid;m public.inventory_movements%rowtype;nm uuid;pay public.payments_v2%rowtype;np uuid;scopes jsonb;
begin select * into sr from public.sale_returns where id=ret for update;if not found then raise exception using errcode='P0001',message='V2_SALE_RETURN_NOT_FOUND';end if;select * into s from public.sales_v2 where id=sr.original_sale_id for update;if not public.v2_has_permission(sr.organization_id,'sales.reverse',s.branch_id)then raise exception using errcode='P0001',message='V2_SALE_REVERSE_REQUIRED';end if;a:=public.v2_current_membership_id(sr.organization_id);c:=public.v2_use_approved_command(approval,sr.organization_id,'sales.reverse',op,p);if(select status='succeeded'from public.command_log where id=c)then return(select entity_id from public.command_log where id=c);end if;x:=public.v2_require_open_sales_shift(sr.organization_id,s.branch_id,s.register_id,sh,d,a);if sr.status='reversed'or sr.reversal_of_id is not null or exists(select 1 from public.sale_returns where reversal_of_id=ret)then raise exception using errcode='P0001',message='V2_SALE_RETURN_ALREADY_REVERSED';end if;
 select jsonb_agg(jsonb_build_object('warehouse_id',scope_row.warehouse_id,'product_id',scope_row.product_id,'batch_id',scope_row.batch_id)order by scope_row.product_id,scope_row.batch_id nulls first)into scopes from(select distinct im.warehouse_id,im.product_id,im.batch_id from public.inventory_movements im join public.sale_return_lines l on l.id=im.source_line_id where l.sale_return_id=ret and im.source_document_type='sale_return' union select distinct im.warehouse_id,im.product_id,null::uuid from public.inventory_movements im join public.sale_return_lines l on l.id=im.source_line_id where l.sale_return_id=ret and im.source_document_type='sale_return')scope_row;perform public.v2_lock_inventory_scopes(sr.organization_id,scopes);
 perform set_config('market_pos.sales_command','on',true);perform set_config('market_pos.sale_reversal_command','on',true);perform set_config('market_pos.inventory_command','on',true);
 insert into public.sale_returns(id,organization_id,original_sale_id,register_id,shift_id,document_number,total_amount,device_id,local_operation_id,posted_by,reversal_of_id)values(r,sr.organization_id,sr.original_sale_id,sr.register_id,sh,n,sr.total_amount,d,op,a,ret);
 for rl in select * from public.sale_return_lines where sale_return_id=ret loop nr:=gen_random_uuid();insert into public.sale_return_lines(id,organization_id,sale_return_id,original_sale_line_id,quantity,refund_amount)values(nr,sr.organization_id,r,rl.original_sale_line_id,rl.quantity,rl.refund_amount);for m in select * from public.inventory_movements where source_document_type='sale_return'and source_line_id=rl.id and quantity_delta>0 loop nm:=gen_random_uuid();insert into public.inventory_movements(id,organization_id,branch_id,warehouse_id,product_id,batch_id,movement_type,quantity_delta,source_document_type,source_document_id,source_line_id,movement_role,reversal_of_id,command_id,created_by)values(nm,m.organization_id,m.branch_id,m.warehouse_id,m.product_id,m.batch_id,'sale_return_reversal',-m.quantity_delta,'sale_return',r,nr,'reversal',m.id,c,a);update public.inventory_balances set on_hand_quantity=on_hand_quantity-m.quantity_delta,last_movement_id=nm,version=version+1 where warehouse_id=m.warehouse_id and product_id=m.product_id and(batch_id=m.batch_id or batch_id is null);end loop;end loop;
 for pay in select * from public.payments_v2 where sale_return_id=ret and amount<0 loop np:=gen_random_uuid();insert into public.payments_v2(id,organization_id,branch_id,register_id,shift_id,sale_return_id,method,amount,currency_code,device_id,local_operation_id,reversal_of_id,created_by)values(np,sr.organization_id,s.branch_id,s.register_id,sh,r,pay.method,-pay.amount,pay.currency_code,d,gen_random_uuid(),pay.id,a);update public.shift_totals set expected_amount=expected_amount-pay.amount,version=version+1,updated_at=now()where shift_id=sh and payment_method=pay.method;perform public.v2_emit_domain_event(sr.organization_id,s.branch_id,d,a,c,approval,'payment',np,'payment.reversal.accepted','PaymentAccepted',jsonb_build_object('reversal_of_id',pay.id,'sale_return_id',r));end loop;
 perform set_config('market_pos.sale_lifecycle_command','on',true);update public.sale_returns set status='reversed'where id=ret;perform set_config('market_pos.sale_lifecycle_command','off',true);perform public.v2_recompute_sale_return_status(s.id);perform public.v2_create_fiscal_intent(sr.organization_id,s.branch_id,s.register_id,sh,null,r,op::text,c,a);perform public.v2_emit_domain_event(sr.organization_id,s.branch_id,d,a,c,approval,'sale_return',r,'sale_return.reversed','SaleReturnReversed',jsonb_build_object('original_id',ret,'reversal_id',r));perform public.v2_complete_inventory_command(c,'sale_return',r,jsonb_build_object('id',r));perform set_config('market_pos.inventory_command','off',true);perform set_config('market_pos.sale_reversal_command','off',true);perform set_config('market_pos.sales_command','off',true);return r;
end$$;

-- Fiscal worker writes only through token-bound SECURITY DEFINER functions.
drop trigger v2_fiscal_documents_context on public.fiscal_documents;drop trigger v2_fiscal_documents_guard on public.fiscal_documents;drop trigger v2_fiscal_documents_delete on public.fiscal_documents;drop trigger v2_fiscal_attempts_append_only on public.fiscal_attempts;
create or replace function public.v2_fiscal_document_write_guard()returns trigger language plpgsql set search_path=''as $$begin if tg_op='INSERT'and coalesce(current_setting('market_pos.sales_command',true),'')='on'then return new;elsif tg_op='UPDATE'and coalesce(current_setting('market_pos.fiscal_worker_command',true),'')='on'then return new;end if;raise exception using errcode='P0001',message='V2_FISCAL_WORKER_CONTEXT_REQUIRED';end$$;
create or replace function public.v2_fiscal_attempt_write_guard()returns trigger language plpgsql set search_path=''as $$begin if tg_op='INSERT'and coalesce(current_setting('market_pos.fiscal_worker_command',true),'')='on'then return new;end if;raise exception using errcode='P0001',message='V2_FISCAL_ATTEMPT_APPEND_ONLY';end$$;
create trigger v2_fiscal_documents_write before insert or update or delete on public.fiscal_documents for each row execute function public.v2_fiscal_document_write_guard();create trigger v2_fiscal_attempts_write before insert or update or delete on public.fiscal_attempts for each row execute function public.v2_fiscal_attempt_write_guard();

create or replace function public.v2_begin_fiscal_attempt(i uuid)returns table(processing_token uuid,attempt_number integer)language plpgsql security definer set search_path=''as $$declare f public.fiscal_documents%rowtype;t uuid:=gen_random_uuid();n integer;begin select * into f from public.fiscal_documents where id=i for update;if not found or f.status not in('pending','failed','deferred')then raise exception using errcode='P0001',message='V2_FISCAL_NOT_RETRYABLE';end if;select coalesce(max(a.attempt_number),0)+1 into n from public.fiscal_attempts a where a.fiscal_document_id=i;perform set_config('market_pos.fiscal_worker_command','on',true);update public.fiscal_documents set status='processing',processing_token=t,processing_started_at=clock_timestamp(),updated_at=now()where id=i;perform set_config('market_pos.fiscal_worker_command','off',true);return query select t,n;end$$;

drop function public.v2_complete_fiscal_attempt(uuid,uuid,integer,text,text,text,jsonb,text);
create function public.v2_complete_fiscal_attempt(i uuid,t uuid,n integer,outcome text,request_hash text,response_code text default null,response_payload jsonb default null,error_code text default null,external_receipt_id text default null,fiscal_sign text default null)returns uuid language plpgsql security definer set search_path=''as $$
declare f public.fiscal_documents%rowtype;existing public.fiscal_attempts%rowtype;a uuid:=gen_random_uuid();ev text;h text;
begin h:=encode(extensions.digest(jsonb_build_object('outcome',outcome,'request_hash',request_hash,'response_code',response_code,'response_payload',response_payload,'error_code',error_code,'external_receipt_id',external_receipt_id,'fiscal_sign',fiscal_sign)::text,'sha256'),'hex');select * into existing from public.fiscal_attempts where fiscal_document_id=i and attempt_number=n;if found then if existing.processing_token is distinct from t then raise exception using errcode='P0001',message='V2_FISCAL_PROCESSING_TOKEN_MISMATCH';end if;if existing.completion_hash is distinct from h then raise exception using errcode='P0001',message='V2_FISCAL_COMPLETION_PAYLOAD_MISMATCH';end if;return existing.id;end if;
 select * into f from public.fiscal_documents where id=i for update;if not found or f.status<>'processing'or f.processing_token<>t then raise exception using errcode='P0001',message='V2_FISCAL_PROCESSING_TOKEN_MISMATCH';end if;if outcome not in('issued','failed','deferred')then raise exception using errcode='P0001',message='V2_FISCAL_OUTCOME_INVALID';end if;if outcome='issued'and nullif(btrim(external_receipt_id),'')is null then raise exception using errcode='P0001',message='V2_FISCAL_RECEIPT_REQUIRED';end if;if outcome='failed'and nullif(btrim(error_code),'')is null then raise exception using errcode='P0001',message='V2_FISCAL_ERROR_REQUIRED';end if;if outcome='deferred'and external_receipt_id is not null then raise exception using errcode='P0001',message='V2_FISCAL_RECEIPT_FORBIDDEN';end if;
 perform set_config('market_pos.fiscal_worker_command','on',true);insert into public.fiscal_attempts(id,organization_id,fiscal_document_id,attempt_number,processing_token,completion_hash,request_hash,outcome,response_code,response_payload,error_code)values(a,f.organization_id,i,n,t,h,$5,$4,$6,$7,$8);update public.fiscal_documents set status=$4,external_receipt_id=case when $4='issued'then $9 else null end,fiscal_sign=case when $4='issued'then $10 else null end,issued_at=case when $4='issued'then clock_timestamp()else null end,processing_token=null,processing_started_at=null,updated_at=now()where id=i;ev:=case $4 when'issued'then'FiscalizationCompleted'when'failed'then'FiscalizationFailed'else'FiscalizationDeferred'end;insert into public.outbox_events(organization_id,aggregate_type,aggregate_id,event_type,payload,correlation_id)values(f.organization_id,'fiscal_document',i,ev,jsonb_build_object('fiscal_document_id',i,'attempt_number',n),i);perform set_config('market_pos.fiscal_worker_command','off',true);return a;
end$$;

revoke all on public.fiscal_documents,public.fiscal_attempts from service_role;revoke execute on function public.v2_require_open_sales_shift(uuid,uuid,uuid,uuid,uuid,uuid),public.v2_recompute_sale_return_status(uuid),public.v2_can_view_shift(uuid,uuid,uuid),public.v2_strict_financial_immutable(),public.v2_sale_line_immutable(),public.v2_sale_return_guard(),public.v2_fiscal_document_write_guard(),public.v2_fiscal_attempt_write_guard()from public,anon,authenticated;
grant execute on function public.v2_can_view_shift(uuid,uuid,uuid),public.v2_fiscal_status_for_sale(uuid),public.v2_fiscal_status_for_return(uuid)to authenticated;
revoke execute on function public.v2_reverse_sale(uuid,uuid,text,uuid,uuid,uuid,jsonb),public.v2_reverse_sale_return(uuid,uuid,text,uuid,uuid,uuid,jsonb)from public,anon;grant execute on function public.v2_reverse_sale(uuid,uuid,text,uuid,uuid,uuid,jsonb),public.v2_reverse_sale_return(uuid,uuid,text,uuid,uuid,uuid,jsonb)to authenticated;
revoke execute on function public.v2_complete_fiscal_attempt(uuid,uuid,integer,text,text,text,jsonb,text,text,text)from public,anon,authenticated;grant execute on function public.v2_begin_fiscal_attempt(uuid),public.v2_complete_fiscal_attempt(uuid,uuid,integer,text,text,text,jsonb,text,text,text)to service_role;
